//! 🧪️ Complete receiving outcomes stay resident until a separately funded same-Source transfer.
use semio_framework_value_native_decoding::*;
use semio_framework_value_control_contract::*;
use std::{mem::{size_of,ManuallyDrop},sync::{Arc,atomic::{AtomicUsize,Ordering}}};
#[path="../../🧪️tests/source-bank.rs"]mod source_bank;
use source_bank::Bank;
fn law()->serde_json::Value{serde_json::from_str(include_str!("retained-outcome.json")).unwrap()}
fn semantic_demand()->RetirementDemand{RetirementDemand{copy_bytes:2*size_of::<Option<ValueError>>(),depth:1,..Default::default()}}
struct Semantic{source:Arc<OriginalSourceTurnIssuer>,error:ManuallyDrop<Option<ValueError>>,calls:Arc<AtomicUsize>}
impl OriginalEffectProducer for Semantic{
 type Output=RetainedCloneStep;type Failure=ValueError;type Context<'turn,'source>=&'turn OriginalSourceTurn where 'source:'turn;
 fn validate_context<'turn,'source>(&self,c:&Self::Context<'turn,'source>)->Result<(),ValueError>where 'source:'turn{self.source.validate(c).map_err(Into::into)}
 fn source_turn<'turn,'source>(&self,c:&Self::Context<'turn,'source>)->Option<OriginalSourceTurnIdentity>where 'source:'turn{Some(c.identity())}
 fn receive<'a,'turn,'source>(&mut self,_:&mut Self::Context<'turn,'source>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'a,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'a,RetainedCloneStep,ValueError>,ValueError>where 'source:'turn{
  let d=semantic_demand();if !retained_clone_grant_admits(effect.grant(),d)||effect.remaining_work_units()?<1{return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}assert!(effect.performed(1)?);self.calls.fetch_add(1,Ordering::SeqCst);let progress=RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()};Ok(reply.complete(Err(self.error.take().unwrap().with_retained_progress(progress))))
 }
 fn recover<'a,'turn,'source>(&mut self,_:&mut Self::Context<'turn,'source>,_:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'a,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'a,RetainedCloneStep,ValueError>,ValueError>where 'source:'turn{Ok(reply.pending())}
}
struct TransferContext<'a>{turn:&'a OriginalSourceTurn,frame:&'a mut NativeReceivingEffect<ValueError>,output:&'a mut Option<NativeReceivingEffectOutcome<ValueError>>}
struct Transfer{source:Arc<OriginalSourceTurnIssuer>,interrupt:bool,calls:Arc<AtomicUsize>,recovers:Arc<AtomicUsize>}
impl OriginalEffectProducer for Transfer{
 type Output=RetainedCloneStep;type Failure=ValueError;type Context<'turn,'source>=TransferContext<'turn>where 'source:'turn;
 fn validate_context<'turn,'source>(&self,c:&Self::Context<'turn,'source>)->Result<(),ValueError>where 'source:'turn{self.source.validate(c.turn).map_err(Into::into)}
 fn source_turn<'turn,'source>(&self,c:&Self::Context<'turn,'source>)->Option<OriginalSourceTurnIdentity>where 'source:'turn{Some(c.turn.identity())}
 fn receive<'a,'turn,'source>(&mut self,c:&mut Self::Context<'turn,'source>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'a,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'a,RetainedCloneStep,ValueError>,ValueError>where 'source:'turn{
  self.calls.fetch_add(1,Ordering::SeqCst);let was_ready=c.frame.transfer_ready();let answer=c.frame.transfer_into(c.output,effect,reply)?;if self.interrupt&&was_ready&&!c.frame.transfer_ready()&&c.output.is_some(){self.interrupt=false;assert!(answer.is_recorded());panic!("original typed outcome and transfer reply recorded before unwind")}Ok(answer)
 }
 fn recover<'a,'turn,'source>(&mut self,c:&mut Self::Context<'turn,'source>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'a,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'a,RetainedCloneStep,ValueError>,ValueError>where 'source:'turn{self.recovers.fetch_add(1,Ordering::SeqCst);c.frame.transfer_into(c.output,effect,reply)}
}
fn step(bank:&mut Bank,control:&mut NativeDecodeControl<'_>,frame:&mut NativeReceivingEffect<ValueError>,output:&mut Option<NativeReceivingEffectOutcome<ValueError>>,meta:&mut NativeReceivingEffect<ValueError>,producer:&mut OriginalEffectAuthority<Transfer>,demand:RetirementDemand,work:u64)->NativeReceivingEffectPoll<ValueError>{
 bank.run_with_turn(control,|turn,control|{let mut context=TransferContext{turn,frame,output};control.receive_original_effect(demand,work,meta,producer,|_,effect,producer,action|producer.drive(&mut context,effect,action))}).unwrap()
}
fn complete(poll:NativeReceivingEffectPoll<ValueError>)->NativeReceivingEffectOutcome<ValueError>{match poll{NativeReceivingEffectPoll::Complete(turn)=>turn,NativeReceivingEffectPoll::Pending{..}=>panic!("synchronous Source should settle its recorded reply")}}
#[test]fn actual_receiving_result_requires_original_funding_and_survives_transfer_unwind(){
 let law=law();let mut bank=Bank::from_stock(&law["stock"],false);let mut foreign=Bank::from_stock(&law["stock"],false);let semantic_calls=Arc::new(AtomicUsize::new(0));let transfer_calls=Arc::new(AtomicUsize::new(0));let transfer_recovers=Arc::new(AtomicUsize::new(0));let error=ValueError::new(ValueRefusalKind::InvalidValue,law["message"].as_str().unwrap().to_owned());let pointer=error.message.as_ptr();let mut semantic=OriginalEffectAuthority::new(Semantic{source:bank.source.clone(),error:ManuallyDrop::new(Some(error)),calls:semantic_calls.clone()});let mut transfer=OriginalEffectAuthority::new(Transfer{source:bank.source.clone(),interrupt:true,calls:transfer_calls.clone(),recovers:transfer_recovers.clone()});let mut foreign_transfer=OriginalEffectAuthority::new(Transfer{source:foreign.source.clone(),interrupt:false,calls:Arc::new(AtomicUsize::new(0)),recovers:Arc::new(AtomicUsize::new(0))});let mut observer=|_|true;let mut control=NativeDecodeControl::new(0,&mut observer);let mut frame=NativeReceivingEffect::default();let mut meta=NativeReceivingEffect::default();let mut foreign_meta=NativeReceivingEffect::default();let mut output=None;bank.wallet.lock().unwrap().reject=true;
 let state=bank.run_with_turn(&mut control,|turn,control|{let mut context=turn;control.receive_original_effect_retained(semantic_demand(),1,&mut frame,&mut semantic,&mut context)}).unwrap();assert_eq!(state,NativeReceivingEffectState::Pending{work:law["semanticWork"].as_u64().unwrap()as u128});bank.wallet.lock().unwrap().reject=false;bank.run(&mut control,|native|frame.finish_child_work_for_payout(native)).unwrap();let(mut completion,mut payout)=(None,ReceiptPayout::default());{let mut context=(&mut frame,&mut completion);receipt_payout(&mut bank,&mut control,&mut payout,OriginalConstructionCompletion::demand(),&mut context,|context,native,physical,effect|context.0.stage_receipt_completion(native,physical,context.1,effect),|context,native,physical,proof|native.publish_construction_completion(context.1.as_mut().unwrap(),physical,proof));}{let mut context=(&mut frame,&mut completion);receipt_payout(&mut bank,&mut control,&mut payout,OriginalReceivingPrimary::receipt_completion_demand(),&mut context,|context,native,physical,effect|context.0.stage_published_receipt_completion(native,context.1,physical,effect),|context,native,physical,proof|context.0.publish_receipt_completion(native,physical,proof));}assert!(completion.is_none());let state=bank.run_with_turn(&mut control,|turn,control|{let mut context=turn;control.receive_original_effect_retained(semantic_demand(),1,&mut frame,&mut semantic,&mut context)}).unwrap();assert_eq!(state,NativeReceivingEffectState::Ready{work:0});let repeated=bank.run_with_turn(&mut control,|turn,control|{let mut context=turn;control.receive_original_effect_retained(semantic_demand(),1,&mut frame,&mut semantic,&mut context)}).unwrap();assert_eq!(repeated,NativeReceivingEffectState::Ready{work:law["readyRepeatWork"].as_u64().unwrap()as u128});assert!(frame.transfer_ready());assert!(!semantic.has_pending_action());assert!(!control.has_pending_work());assert!(output.is_none());assert_eq!(semantic_calls.load(Ordering::SeqCst),1);bank.wallet.lock().unwrap().reject=false;let demand=frame.transfer_demand().unwrap();let mut unready=NativeReceivingEffect::default();let denied=complete(step(&mut bank,&mut control,&mut unready,&mut output,&mut meta,&mut transfer,demand,1));assert!(denied.result.is_err());assert_eq!(denied.work,0);assert_eq!(unready.phase(),NativeReceivingEffectPhase::Empty);assert!(output.is_none()&&frame.transfer_ready());
 let rejected=RetirementDemand{copy_bytes:0,..demand};let denied=complete(step(&mut bank,&mut control,&mut frame,&mut output,&mut meta,&mut transfer,demand,0));assert_eq!(denied.work,law["deniedWork"].as_u64().unwrap()as u128);assert_eq!(denied.result.unwrap().progress(),Default::default());assert!(output.is_none()&&frame.transfer_ready());let denied=complete(step(&mut bank,&mut control,&mut frame,&mut output,&mut meta,&mut transfer,rejected,1));assert_eq!(denied.work,0);denied.result.unwrap();assert!(output.is_none()&&frame.transfer_ready());
 output=Some(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0});let denied=complete(step(&mut bank,&mut control,&mut frame,&mut output,&mut meta,&mut transfer,demand,1));assert!(denied.result.is_err());assert_eq!(output.as_ref().unwrap().work,0);assert!(frame.transfer_ready());output.take();
 let denied=complete(step(&mut foreign,&mut control,&mut frame,&mut output,&mut foreign_meta,&mut foreign_transfer,demand,1));assert!(denied.result.is_err());assert_eq!(denied.work,0);assert!(output.is_none()&&frame.transfer_ready());assert_eq!(foreign.wallet.lock().unwrap().fuel,law["stock"]["fuel"].as_u64().unwrap()as u128);
 let before=transfer_calls.load(Ordering::SeqCst);let interrupted=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||step(&mut bank,&mut control,&mut frame,&mut output,&mut meta,&mut transfer,demand,1)));assert!(interrupted.is_err());assert!(meta.has_pending_recovery()&&transfer.has_pending_action());assert!(output.is_some());assert!(!frame.transfer_ready());assert_eq!(frame.phase(),NativeReceivingEffectPhase::Empty);
 let settled=complete(step(&mut bank,&mut control,&mut frame,&mut output,&mut meta,&mut transfer,demand,1));assert_eq!(settled.work,law["transferWork"].as_u64().unwrap()as u128);assert_eq!(settled.result.unwrap().progress().copied_bytes,demand.copy_bytes);assert_eq!(transfer_calls.load(Ordering::SeqCst),before+1);assert_eq!(transfer_recovers.load(Ordering::SeqCst),0);assert_eq!(semantic_calls.load(Ordering::SeqCst),1);assert!(!meta.has_pending_recovery()&&!control.has_pending_work());
 let mut ack=OriginalEffectAuthority::new(Acknowledge{source:bank.source.clone(),interrupt:false,calls:Arc::new(AtomicUsize::new(0)),recovers:Arc::new(AtomicUsize::new(0))});let demand=NativeReceivingEffect::<ValueError>::acknowledge_success_demand::<ValueError>().unwrap();let refused=complete(acknowledge(&mut bank,&mut control,&mut output,&mut meta,&mut ack,demand,1));assert!(refused.result.is_err());assert_eq!(refused.work,0);assert_eq!(output.is_none(),law["acknowledgement"]["errorAccepted"].as_bool().unwrap());assert!(ack.into_producer().is_ok());
 let outcome=output.take().unwrap();assert_eq!(outcome.work,law["transferredWork"].as_u64().unwrap()as u128);let mut failure=outcome.result.unwrap_err();assert_eq!(failure.child.as_ref().unwrap().message.as_ptr(),pointer);assert!(failure.receiving.receipt_completion().is_some());assert_eq!(failure.retained_progress().copied_bytes,semantic_demand().copy_bytes);let release=failure.receiving.receipt_completion_release_demand().unwrap().unwrap();receipt_payout(&mut bank,&mut control,&mut payout,release,&mut failure.receiving,|receiving,native,physical,effect|native.retire_receiving_completion(receiving,physical,effect),|_,_,_,_|Ok(true));assert!(failure.receiving.receipt_completion().is_none());assert_eq!(control.actual_work(),(law["semanticWork"].as_u64().unwrap()+law["transferWork"].as_u64().unwrap()+3)as u128);assert_eq!(law["stock"]["fuel"].as_u64().unwrap()as u128-bank.wallet.lock().unwrap().fuel,control.actual_work());assert!(semantic.into_producer().is_ok());assert!(transfer.into_producer().is_ok());assert!(foreign_transfer.into_producer().is_ok());
}

struct Counter{source:Arc<OriginalSourceTurnIssuer>,value:u64}
impl OriginalEffectProducer for Counter{
 type Output=RetainedCloneStep;type Failure=ValueError;type Context<'turn,'source>=&'turn OriginalSourceTurn where 'source:'turn;
 fn validate_context<'turn,'source>(&self,c:&Self::Context<'turn,'source>)->Result<(),ValueError>where 'source:'turn{self.source.validate(c).map_err(Into::into)}
 fn source_turn<'turn,'source>(&self,c:&Self::Context<'turn,'source>)->Option<OriginalSourceTurnIdentity>where 'source:'turn{Some(c.identity())}
 fn receive<'reply,'turn,'source>(&mut self,_:&mut Self::Context<'turn,'source>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,ValueError>,ValueError>where 'source:'turn{assert!(effect.performed(1)?);self.value+=1;Ok(reply.complete(Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:size_of::<u64>(),..Default::default()}))))}
 fn recover<'reply,'turn,'source>(&mut self,_:&mut Self::Context<'turn,'source>,_:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,ValueError>,ValueError>where 'source:'turn{Ok(reply.pending())}
}
struct AcknowledgeContext<'a>{turn:&'a OriginalSourceTurn,outcome:&'a mut Option<NativeReceivingEffectOutcome<ValueError>>}
struct Acknowledge{source:Arc<OriginalSourceTurnIssuer>,interrupt:bool,calls:Arc<AtomicUsize>,recovers:Arc<AtomicUsize>}
impl OriginalEffectProducer for Acknowledge{
 type Output=RetainedCloneStep;type Failure=ValueError;type Context<'turn,'source>=AcknowledgeContext<'turn>where 'source:'turn;
 fn validate_context<'turn,'source>(&self,c:&Self::Context<'turn,'source>)->Result<(),ValueError>where 'source:'turn{self.source.validate(c.turn).map_err(Into::into)}
 fn source_turn<'turn,'source>(&self,c:&Self::Context<'turn,'source>)->Option<OriginalSourceTurnIdentity>where 'source:'turn{Some(c.turn.identity())}
 fn receive<'reply,'turn,'source>(&mut self,c:&mut Self::Context<'turn,'source>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,ValueError>,ValueError>where 'source:'turn{self.calls.fetch_add(1,Ordering::SeqCst);let answer=NativeReceivingEffect::<ValueError>::acknowledge_success_into(c.outcome,effect,reply)?;if self.interrupt&&c.outcome.is_none(){self.interrupt=false;assert!(answer.is_recorded());panic!("successful original receipt and paid acknowledgement are recorded")}Ok(answer)}
 fn recover<'reply,'turn,'source>(&mut self,c:&mut Self::Context<'turn,'source>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,ValueError>,ValueError>where 'source:'turn{self.recovers.fetch_add(1,Ordering::SeqCst);NativeReceivingEffect::<ValueError>::acknowledge_success_into(c.outcome,effect,reply)}
}
fn acknowledge(bank:&mut Bank,control:&mut NativeDecodeControl<'_>,outcome:&mut Option<NativeReceivingEffectOutcome<ValueError>>,meta:&mut NativeReceivingEffect<ValueError>,authority:&mut OriginalEffectAuthority<Acknowledge>,demand:RetirementDemand,work:u64)->NativeReceivingEffectPoll<ValueError>{bank.run_with_turn(control,|turn,control|{let mut context=AcknowledgeContext{turn,outcome};control.receive_original_effect(demand,work,meta,authority,|_,effect,authority,action|authority.drive(&mut context,effect,action))}).unwrap()}
#[test]fn actual_success_acknowledgement_is_paid_and_never_reposts_the_original_receipt(){
 let law=law();let mut bank=Bank::from_stock(&law["stock"],false);let calls=Arc::new(AtomicUsize::new(0));let recovers=Arc::new(AtomicUsize::new(0));let mut counter=OriginalEffectAuthority::new(Counter{source:bank.source.clone(),value:0});let mut transfer=OriginalEffectAuthority::new(Transfer{source:bank.source.clone(),interrupt:false,calls:Arc::new(AtomicUsize::new(0)),recovers:Arc::new(AtomicUsize::new(0))});let mut ack=OriginalEffectAuthority::new(Acknowledge{source:bank.source.clone(),interrupt:true,calls:calls.clone(),recovers:recovers.clone()});let mut observer=|_|true;let mut control=NativeDecodeControl::new(0,&mut observer);let mut frame=NativeReceivingEffect::default();let mut meta=NativeReceivingEffect::default();let mut outcome=None;let semantic=RetirementDemand{copy_bytes:size_of::<u64>(),depth:1,..Default::default()};let law_witness:serde_json::Value=serde_json::from_str(include_str!("../🧳️frame/🧪️tests/🪪️witness/case.json")).unwrap();let mut sibling=bank.sibling_authority();let identity=bank.run_with_turn(&mut control,|turn,control|{frame.bind_original(control)?;assert!(frame.prepare_original(control,semantic,1)?);frame.with_granted_construction(control,|witness|{assert_eq!(witness.source_turn(),Some(turn.identity()));assert_eq!(witness.phase(),OriginalConstructionPhase::Granted);witness.identity()})}).unwrap();assert!(law_witness[0]["exposed"].as_bool().unwrap());assert!(sibling.run(&mut control,|control|frame.with_granted_construction(control,|_|())).is_err());assert!(!law_witness[1]["exposed"].as_bool().unwrap());let state=bank.run_with_turn(&mut control,|turn,control|{frame.with_granted_construction(control,|witness|assert_eq!(witness.identity(),identity))?;assert!(frame.drive_original_producer_bound(control,&mut counter,|_,effect,producer,action,binding|{assert_eq!(binding.action(),identity);assert!(binding.matches_effect(effect));let mut context=turn;producer.drive(&mut context,effect,action)})?);let mut context=turn;control.receive_original_effect_retained(semantic,1,&mut frame,&mut counter,&mut context)}).unwrap();assert_eq!(state,NativeReceivingEffectState::Ready{work:1});let d=frame.transfer_demand().unwrap();complete(step(&mut bank,&mut control,&mut frame,&mut outcome,&mut meta,&mut transfer,d,1)).result.unwrap();assert_eq!(outcome.as_ref().unwrap().work,0);let d=NativeReceivingEffect::<ValueError>::acknowledge_success_demand::<ValueError>().unwrap();let mut unreported=Some(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:1});let before=bank.wallet.lock().unwrap().fuel;let rejected=complete(acknowledge(&mut bank,&mut control,&mut unreported,&mut meta,&mut ack,d,1));assert!(rejected.result.is_err());assert_eq!(rejected.work,0);assert_eq!(unreported.is_none(),law["acknowledgement"]["unreportedAccepted"].as_bool().unwrap());assert_eq!(unreported.as_ref().unwrap().work,1);assert_eq!(bank.wallet.lock().unwrap().fuel,before);
 for(d,work)in[(d,0),(RetirementDemand{copy_bytes:d.copy_bytes-1,..d},1)]{let before=bank.wallet.lock().unwrap().fuel;let denied=complete(acknowledge(&mut bank,&mut control,&mut outcome,&mut meta,&mut ack,d,work));assert_eq!(denied.work,0);assert_eq!(denied.result.unwrap().progress(),Default::default());assert_eq!(outcome.as_ref().unwrap().result.as_ref().unwrap().progress().copied_bytes,semantic.copy_bytes);assert_eq!(bank.wallet.lock().unwrap().fuel,before);}
 let before=calls.load(Ordering::SeqCst);let interrupted=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||acknowledge(&mut bank,&mut control,&mut outcome,&mut meta,&mut ack,d,1)));assert!(interrupted.is_err());assert!(outcome.is_none()&&meta.has_pending_recovery());let receipt=complete(acknowledge(&mut bank,&mut control,&mut outcome,&mut meta,&mut ack,d,1));assert_eq!(receipt.work,1);let progress=receipt.result.unwrap().progress();assert_eq!(progress.copied_bytes,d.copy_bytes);assert_ne!(progress.copied_bytes,d.copy_bytes+semantic.copy_bytes);assert_eq!(calls.load(Ordering::SeqCst),before+1);assert_eq!(recovers.load(Ordering::SeqCst),0);assert_eq!(counter.producer().value,1);assert_eq!(control.actual_work(),3);assert_eq!(law["stock"]["fuel"].as_u64().unwrap()as u128-bank.wallet.lock().unwrap().fuel,3);assert!(counter.into_producer().is_ok());assert!(transfer.into_producer().is_ok());assert!(ack.into_producer().is_ok());
}

#[derive(Default)]
struct ReceiptPayout{physical:Option<OriginalConstructionAction>,work:Option<OriginalWorkActionIdentity>,receipt:Option<OriginalWorkPerformedReceipt>,partial:Option<OriginalWorkPartialOutcome>,proof:Option<OriginalWorkActionProof>,actual:Option<usize>,progress:Option<RetainedCloneProgress>}
impl Drop for ReceiptPayout{fn drop(&mut self){assert!(std::thread::panicking()||self.physical.is_none()&&self.work.is_none()&&self.receipt.is_none()&&self.partial.is_none()&&self.proof.is_none()&&self.progress.is_none(),"test payout retains original owners")}}
fn receipt_payout<C>(bank:&mut Bank,control:&mut NativeDecodeControl<'_>,state:&mut ReceiptPayout,demand:RetirementDemand,context:&mut C,operation:impl FnOnce(&mut C,&mut NativeDecodeControl<'_>,&OriginalConstructionAction,&mut RetainedAllocationEffect<'_>)->RetainedWorkOutcome<Option<RetainedCloneProgress>,ValueError>,publish:impl FnOnce(&mut C,&mut NativeDecodeControl<'_>,&mut OriginalConstructionAction,&OriginalWorkActionProof)->Result<bool,ValueError>){
 use semio_framework_value_native_receiving_frame::NativeReceivingEffectHost;
 bank.run(control,|native|{let grant=native.construction_grant(demand,&mut state.physical)?.ok_or_else(||ValueError::invariant("original payout quote pending"))??;{let mut work=NativeReceivingEffectHost::original_work(native);assert_eq!(work.prepare(1,&mut state.work)?,Some(true));work.issue_performed(state.work,&mut state.receipt)?}let turn={let mut effect=RetainedAllocationEffect::new(grant,1,&mut state.actual,state.receipt.as_mut().unwrap());operation(context,native,state.physical.as_ref().unwrap(),&mut effect)};assert_eq!(turn.work,1);state.progress=turn.result?;{let mut work=NativeReceivingEffectHost::original_work(native);work.claim_performed(state.work,&mut state.receipt)?;assert!(work.settle_partial_into(state.work,&mut state.partial)?);assert!(state.partial.as_ref().unwrap().source_refusal().is_none());drop(state.partial.take());assert!(work.commit(1,state.work,&mut state.proof)?)}let progress=state.progress.take().ok_or_else(||ValueError::invariant("original payout made no progress"))?;assert_eq!(native.submit_constructed_progress(state.physical.as_mut().unwrap(),progress,None)?,Some(OriginalConstructionAcceptStatus::Accepted));assert!(publish(context,native,state.physical.as_mut().unwrap(),state.proof.as_ref().unwrap())?);native.finish_constructed_action(&mut state.physical)?;NativeReceivingEffectHost::original_work(native).finish(&mut state.proof,&mut state.work)?;Ok(())}).unwrap()
}
