fn actual_receipt_refusal_is_published_through_two_paid_completions(){
 let law=law();let mut bank=Bank::from_stock(&law["stock"],false);let error=ValueError::new(ValueRefusalKind::Canceled,String::from("actual native receipt refusal"));let pointer=error.message.as_ptr();bank.wallet.lock().unwrap().post_error=Some(error);let mut semantic=OriginalEffectAuthority::new(Counter{source:bank.source.clone(),value:0});let mut observer=|_|true;let mut control=NativeDecodeControl::new(0,&mut observer);let mut frame=NativeReceivingEffect::<ValueError>::default();let demand=RetirementDemand{copy_bytes:size_of::<u64>(),depth:1,..Default::default()};let state=bank.run_with_turn(&mut control,|turn,native|{let mut context=turn;native.receive_original_effect_retained(demand,1,&mut frame,&mut semantic,&mut context)}).unwrap();assert!(matches!(state,NativeReceivingEffectState::Pending{..}));assert_eq!(semantic.inspect(|p|p.value),1);bank.run(&mut control,|native|frame.finish_child_work_for_payout(native)).unwrap();let(mut completion,mut payout)=(None,ReceiptPayout::default());{let mut context=(&mut frame,&mut completion);receipt_payout(&mut bank,&mut control,&mut payout,OriginalConstructionCompletion::demand(),&mut context,|context,native,physical,effect|context.0.stage_receipt_completion(native,physical,context.1,effect),|context,native,physical,proof|native.publish_construction_completion(context.1.as_mut().unwrap(),physical,proof));}assert_eq!(completion.as_ref().unwrap().refusal().unwrap().message.as_ptr(),pointer);{let mut context=(&mut frame,&mut completion);receipt_payout(&mut bank,&mut control,&mut payout,OriginalReceivingPrimary::receipt_completion_demand(),&mut context,|context,native,physical,effect|context.0.stage_published_receipt_completion(native,context.1,physical,effect),|context,native,physical,proof|context.0.publish_receipt_completion(native,physical,proof));}assert!(completion.is_none());let state=bank.run_with_turn(&mut control,|turn,native|{let mut context=turn;native.receive_original_effect_retained(demand,1,&mut frame,&mut semantic,&mut context)}).unwrap();assert!(matches!(state,NativeReceivingEffectState::Ready{..}));let transfer_calls=Arc::new(AtomicUsize::new(0));let mut transfer=OriginalEffectAuthority::new(Transfer{source:bank.source.clone(),interrupt:false,calls:transfer_calls,recovers:Arc::new(AtomicUsize::new(0))});let(mut meta,mut output)=(NativeReceivingEffect::default(),None);let transfer_demand=frame.transfer_demand().unwrap();let turn=complete(step(&mut bank,&mut control,&mut frame,&mut output,&mut meta,&mut transfer,transfer_demand,1));assert!(turn.result.is_ok());let outcome=output.take().unwrap();let mut failure=outcome.result.unwrap_err();assert_eq!(failure.receiving.receipt_completion().unwrap().message.as_ptr(),pointer);assert!(failure.receiving.receipt_refusal.is_none());let release=failure.receiving.receipt_completion_release_demand().unwrap().unwrap();receipt_payout(&mut bank,&mut control,&mut payout,release,&mut failure.receiving,|receiving,native,physical,effect|native.retire_receiving_completion(receiving,physical,effect),|_,_,_,_|Ok(true));assert!(failure.receiving.receipt_completion().is_none());assert_eq!(law["stock"]["fuel"].as_u64().unwrap()as u128-bank.wallet.lock().unwrap().fuel,control.actual_work());assert!(semantic.into_producer().is_ok());assert!(transfer.into_producer().is_ok());
}

#[test]fn decoder_lends_only_the_actual_work_source_witness(){
 let law:serde_json::Value=serde_json::from_str(include_str!("source-witness.json")).unwrap();let mut bank=Bank::from_stock(&law["stock"],false);let foreign=OriginalSourceTurnIssuer::new().issue().unwrap();let mut observer=|_|true;let mut native=NativeDecodeControl::new(0,&mut observer);let mut called=0usize;
 bank.run_with_turn(&mut native,|turn,native|{let refused=native.with_original_source_witness(foreign.witness(),|_,_|{called+=1;Ok(())});assert_eq!(refused.is_ok(),law["foreignAccepted"].as_bool().unwrap());let identity=native.with_original_source_witness(turn.witness(),|control,witness|{assert_eq!(control.original_work_source_turn()?,Some(witness.identity()));Ok(witness.identity())})?;assert_eq!(identity,turn.identity());Ok(())}).unwrap();assert_eq!(called,law["foreignCallbacks"].as_u64().unwrap() as usize);
 let interrupted=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||{let _=bank.run_with_turn(&mut native,|turn,native|native.with_original_source_witness(turn.witness(),|_,_|->Result<(),ValueError>{panic!("original witness loan unwind")}));}));assert!(interrupted.is_err());bank.run_with_turn(&mut native,|turn,native|native.with_original_source_witness(turn.witness(),|_,same|{assert_eq!(same.identity(),turn.identity());Ok(())})).unwrap();assert_eq!(bank.wallet.lock().unwrap().fuel,u128::from(law["stock"]["fuel"].as_u64().unwrap()));
}
